class CDot11SecAuthKeyMgmtType(TextualConvention, Bits):
    description = 'This is the encryption key management type\n                applied to different encryption key algorithms,\n                like TKIP, WEP, and CKIP. \n                    cckm  -  Cisco Central Key Management \n                    wpa   -  Key management WPA version 1 for TKIP Cipher and\n                             Key management WPA version 2 for AES-CCMP Cipher\n                    wpa1  -  Key management WPA version 1\n                    wpa2  -  Key management WPA version 2'
    status = 'current'
    namedValues = NamedValues(("cckm", 0), ("wpa", 1), ("wpa1", 2), ("wpa2", 3))

class CDot11WiFiPaPreSharedKey(TextualConvention, OctetString):
    description = 'This is a 64-hexadecimal digit Wi-Fi Protected \n                Access Pre-shared Key.  This key is used for \n                association authentication and dynamic encryption\n                key generation.  The key can also be in the form\n                of a character string.'
    status = 'current'
    subtypeSpec = OctetString.subtypeSpec + ValueSizeConstraint(0, 128)

class CDot11SsidString(TextualConvention, OctetString):
    description = 'This is the SSID string defined for IEEE 802.11 \n                wireless LAN devices.'
    status = 'current'
    subtypeSpec = OctetString.subtypeSpec + ValueSizeConstraint(1, 32)

class CDot11VlanName(TextualConvention, OctetString):
    description = 'This is a VLAN name string configured on RADIUS\n                servers.  This should be an alpha-numeric string\n                with at least one alpha.'
    status = 'current'
    subtypeSpec = OctetString.subtypeSpec + ValueSizeConstraint(1, 32)

class CDot11InformationElementType(TextualConvention, Bits):
    description = 'This is the set of Information Elements embedded\n                in the wireless device beacons and probe response\n                and the extended capabilities configurable on the\n                IEs:\n                    ssidl - send SSIDL IE and may advertise extended\n                            capabilities, i.e., 802.1x and WPS;\n                    advertisement - send SSID name and capabilities\n                                    in the SSIDL IE;\n                    wps - set WPS flag in the extended capabilities.'
    status = 'current'
    namedValues = NamedValues(("ssidl", 0), ("advertisement", 1), ("wps", 2))

